 using namespace std::chrono_literals;
 using namespace Qt::StringLiterals;

+// pam_faillock says how long the account stays locked with a message like "(10 minutes left to unlock)". Match it against
+// Linux-PAM's own translations so that it is found in any language.
+static int faillockMinutesLeft(const QString &msg)
+{
+#if HAVE_LIBINTL
+    static const QRegularExpression number(u"[0-9]+"_s);
+    for (const auto &match : number.globalMatch(msg)) {
+        const int minutes = match.captured().toInt();
+        const char *plural = dngettext("Linux-PAM", "(%d minute left to unlock)", "(%d minutes left to unlock)", minutes);
+        // older Linux-PAM versions have no plural form for it
+        const char *old = dgettext("Linux-PAM", "(%d minutes left to unlock)");
+        if (msg == QString::asprintf(plural, minutes) || msg == QString::asprintf(old, minutes)) {
+            return minutes;
+        }
+    }
+#else
+    Q_UNUSED(msg)
+#endif
+    return 0;
+}
