@@ -243,14 +270,64 @@ void PamAuthenticator::StartFailedDelay(uint useconds)
     Q_EMIT loginFailedDelayStarted(useconds);
 }

+int PamAuthenticator::lockoutMinutesLeft() const
+{
+    return m_lockoutMinutesLeft;
+}
+
+bool PamAuthenticator::handleLockoutMessage(const QString &msg)
+{
+    const int minutes = faillockMinutesLeft(msg);
+    if (minutes <= 0) {
+        return false;
+    }
+
+    m_lockoutMessageSeen = true;
+    // The message is rounded up to whole minutes, so every new one can only narrow down when the lockout ends
+    const QDateTime until = QDateTime::currentDateTimeUtc().addSecs(minutes * 60);
+    if (!m_lockedOutUntil.isValid() || until < m_lockedOutUntil) {
+        m_lockedOutUntil = until;
+    }
+    if (!m_lockoutTimer) {
+        m_lockoutTimer = new QTimer(this);
+        m_lockoutTimer->setInterval(1s);
+        connect(m_lockoutTimer, &QTimer::timeout, this, &PamAuthenticator::updateLockout);
+    }
+    m_lockoutTimer->start();
+    updateLockout();
+    return true;
+}
+
+void PamAuthenticator::updateLockout()
+{
+    const qint64 msecsLeft = m_lockedOutUntil.isValid() ? QDateTime::currentDateTimeUtc().msecsTo(m_lockedOutUntil) : 0;
+    const int minutes = msecsLeft > 0 ? int((msecsLeft + 59999) / 60000) : 0;
+    if (minutes == 0) {
+        m_lockedOutUntil = {};
+        if (m_lockoutTimer) {
+            m_lockoutTimer->stop();
+        }
+    }
+    if (m_lockoutMinutesLeft != minutes) {
+        m_lockoutMinutesLeft = minutes;
+        Q_EMIT lockoutMinutesLeftChanged();
+    }
+}
+
 void PamAuthenticator::InfoMessage(const QString &msg)
 {
+    if (handleLockoutMessage(msg)) {
+        return;
+    }
     m_infoMessage = msg;
     Q_EMIT infoMessage(msg);
 }

 void PamAuthenticator::ErrorMessage(const QString &msg)
 {
+    if (handleLockoutMessage(msg)) {
+        return;
+    }
     m_errorMessage = msg;
     Q_EMIT errorMessage(msg);
 }
