+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -393,6 +393,9 @@ Item {
                     if (root.notification) {
                         parts.push(root.notification);
                     }
+                    if (authenticator.lockoutMinutesLeft > 0) {
+                        parts.push(i18ndcp("plasma_shell_org.kde.plasma.desktop", "@info:status", "Try again in %1 minute", "Try again in %1 minutes", authenticator.lockoutMinutesLeft));
+                    }
                     return parts.join(" • ");
                 }

